import{_ as t,o as a,c as s,l as n,t as i,N as r}from"./chunks/framework.Bbd9fWQx.js";const E=JSON.parse('{"title":"nss | x-cmd man (man5) | Name Service Switch configuration file","titleTemplate":false,"description":"x-cmd man (man5 Manual Page) | nss - Name Service Switch configuration file","frontmatter":{"pageClass":"x-man","head":[["meta",{"name":"og:title","content":"nss | x-cmd man (man5) | Name Service Switch configuration file"}],["meta",{"name":"og:description","content":"x-cmd man (man5 Manual Page) | nss - Name Service Switch configuration file"}]]},"headers":[],"params":{"isMan":true,"man":"nss","category":"man5","desc":"Name Service Switch configuration file"},"relativePath":"man5/nss.md","filePath":"man5/nss.md"}'),o={name:"man5/nss.md"},h={class:"visually-hidden"},l=r(`<h2 id="name" tabindex="-1">NAME <a class="header-anchor" href="#name" aria-label="Permalink to &quot;NAME&quot;">​</a></h2><p>nss - Name Service Switch configuration file</p><h2 id="description" tabindex="-1">DESCRIPTION <a class="header-anchor" href="#description" aria-label="Permalink to &quot;DESCRIPTION&quot;">​</a></h2><p>Each call to a function which retrieves data from a system database like the password or group database is handled by the Name Service Switch implementation in the GNU C library. The various services provided are implemented by independent modules, each of which naturally varies widely from the other.</p><p>The default implementations coming with the GNU C library are by default conservative and do not use unsafe data. This might be very costly in some situations, especially when the databases are large. Some modules allow the system administrator to request taking shortcuts if these are known to be safe. It is then the system administrator&#39;s responsibility to ensure the assumption is correct.</p><p>There are other modules where the implementation changed over time. If an implementation used to sacrifice speed for memory consumption, it might create problems if the preference is switched.</p><p>The <em>/etc/default/nss</em> file contains a number of variable assignments. Each variable controls the behavior of one or more NSS modules. White spaces are ignored. Lines beginning with &#39;#&#39; are treated as comments.</p><p>The variables currently recognized are:</p><dl><dt><strong>NETID_AUTHORITATIVE =</strong> <em>TRUE</em>|<em>FALSE</em></dt><dd>If set to TRUE, the NIS backend for the <strong>initgroups</strong>(3) function will accept the information from the <em>netid.byname</em> NIS map as authoritative. This can speed up the function significantly if the <em>group.byname</em> map is large. The content of the <em>netid.byname</em> map is used <strong>as is</strong>. The system administrator has to make sure it is correctly generated.</dd><dt><strong>SERVICES_AUTHORITATIVE =</strong> <em>TRUE</em>|<em>FALSE</em></dt><dd>If set to TRUE, the NIS backend for the <strong>getservbyname</strong>(3) and <strong>getservbyname_r</strong>(3) functions will assume that the <em>services.byservicename</em> NIS map exists and is authoritative, particularly that it contains both keys with /proto and without /proto for both primary service names and service aliases. The system administrator has to make sure it is correctly generated.</dd><dt><strong>SETENT_BATCH_READ =</strong> <em>TRUE</em>|<em>FALSE</em></dt><dd>If set to TRUE, the NIS backend for the <strong>setpwent</strong>(3) and <strong>setgrent</strong>(3) functions will read the entire database at once and then hand out the requests one by one from memory with every corresponding <strong>getpwent</strong>(3) or <strong>getgrent</strong>(3) call respectively. Otherwise, each <strong>getpwent</strong>(3) or <strong>getgrent</strong>(3) call might result in a network communication with the server to get the next entry.</dd></dl><h2 id="files" tabindex="-1">FILES <a class="header-anchor" href="#files" aria-label="Permalink to &quot;FILES&quot;">​</a></h2><p><em>/etc/default/nss</em></p><h2 id="examples" tabindex="-1">EXAMPLES <a class="header-anchor" href="#examples" aria-label="Permalink to &quot;EXAMPLES&quot;">​</a></h2><p>The default configuration corresponds to the following configuration file:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">NETID_AUTHORITATIVE</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">FALSE</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">SERVICES_AUTHORITATIVE</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">FALSE</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">SETENT_BATCH_READ</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">FALSE</span></span></code></pre></div><h2 id="see-also" tabindex="-1">SEE ALSO <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;SEE ALSO&quot;">​</a></h2><p><em>nsswitch.conf</em></p>`,16);function m(e,c,d,p,g,u){return a(),s("div",null,[n("h1",h,i(e.$params.man),1),l])}const S=t(o,[["render",m]]);export{E as __pageData,S as default};
